"""Generate the inline C++ requirement badges used in project documentation."""

from pathlib import Path


BADGES = {17: "#2463a6", 20: "#14756d", 23: "#6b47ae", 26: "#956015"}
OUTPUT = Path(__file__).resolve().parents[1] / "docs" / "assets" / "badges"
TEMPLATE = '''<svg xmlns="http://www.w3.org/2000/svg" width="86" height="22" viewBox="0 0 86 22"
     role="img" aria-label="Requires C++{version} or later">
  <title>Requires C++{version} or later</title>
  <!-- Generated by tools/generate_cpp_badges.py. -->
  <defs>
    <clipPath id="cpp{version}-clip"><rect width="86" height="22" rx="4"/></clipPath>
    <linearGradient id="cpp{version}-shine" x2="0" y2="1">
      <stop stop-color="#fff" stop-opacity=".08"/>
      <stop offset="1" stop-color="#000" stop-opacity=".08"/>
    </linearGradient>
  </defs>
  <g clip-path="url(#cpp{version}-clip)">
    <rect width="86" height="22" fill="#243247"/>
    <path d="M50 0H86V22H50L55 11Z" fill="{color}"/>
    <rect width="86" height="22" fill="url(#cpp{version}-shine)"/>
  </g>
  <path d="M9 7L5 11L9 15" fill="none" stroke="#b9cce5" stroke-width="1.5"
        stroke-linecap="round" stroke-linejoin="round"/>
  <g fill="#fff" text-anchor="middle" font-family="Verdana,DejaVu Sans,sans-serif" font-weight="700">
    <text x="30" y="15" font-size="11" letter-spacing=".2">C++</text>
    <text x="69" y="15" font-size="12">{version}</text>
  </g>
  <rect x=".5" y=".5" width="85" height="21" rx="3.5" fill="none"
        stroke="#fff" stroke-opacity=".16"/>
</svg>
'''


def main():
    OUTPUT.mkdir(parents=True, exist_ok=True)
    for version, color in BADGES.items():
        path = OUTPUT / f"cpp{version}.svg"
        with path.open("w", encoding="utf-8", newline="\n") as badge:
            badge.write(TEMPLATE.format(version=version, color=color))
        print(path.relative_to(OUTPUT.parents[2]))


if __name__ == "__main__":
    main()
